national_truce_dec =  --国战说明
{
	{"[Правила]","Территории войны фракций делятся на 4 зоны: земли Врат Дракона и Тигра, земли Белого Лотоса, земли Секты Ракшасы и нейтральная зона."},
	{"","У каждой фракции есть главная статуя божества, которую нельзя захватить. Когда игрок гибнет, он телепортируется к ней для возрождения."},
	{"","Тот, кто убьёт последнего NPC на точке, делает свою фракцию владельцем этой точки; во время события уже занятые точки можно продолжать оспаривать."},
	{"","Если за один опорный пункт бьются больше двух сил, игроки в его зоне могут атаковать и NPC, охраняющих пункт, и игроков других сил, которые его штурмуют."},
	{"","Как бы ни различалось число атакующих и защитников, условие захвата опорного пункта всегда одно: «убить последнего NPC, охраняющего этот пункт». Как только пункт сменит хозяина, всех игроков других сил из него выбросит и принудительно перенесёт к главной статуе."},
	{"","При выполнении определённых условий игрок может использовать тактические манёвры, такие как прорыв или окружение."},
	{"","По окончании войны фракций побеждает фракция, захватившая больше всего баз."},
	{"","По окончании войны фракций побеждает фракция, захватившая больше всего баз."},
	{"[Бой]","[Ожидание] Войдя на территорию, ты автоматически переходишь в состояние ожидания; в этом состоянии тебя может найти вражеский игрок, и тогда начинается бой."},
	{"","[Поиск врага] После нажатия «Атака» ты переходишь в состояние активного поиска цели противника; после каждой атаки действует 10-секундная перезарядка. Можно атаковать игроков определённой фракции."},
	{"","[Бой] В режиме поиска врага после каждой победы добавляется 30 сек. перезарядки; когда время накопится до 1 мин., наступает перезарядка, во время которой нельзя атаковать. За 200 очков боевого духа перезарядку можно сбросить. После победы ниндзя игрока не восстанавливают потерянные ОЗ, но чакра сбрасывается."},
	{"","[Пал] После поражения в бою ты переходишь в состояние «Пал»; в этом состоянии нельзя отдавать приказы."},
	{"","[Воскрешение] После гибели ты телепортируешься к главной статуе и ждёшь 1 минуту до воскрешения; можно потратить 500 боевого духа, чтобы воскреснуть мгновенно."},
	{"","[Отступление] Можно потратить 200 боевого духа и потерять 20% максимального здоровья, чтобы принудительно отступить с территории, где идёт бой."},
	{"","[Прорыв] Когда атакующих вдвое больше, чем защитников, можно применить тактику прорыва."},
	{"","[Окружение] Когда соседние с точкой базы захвачены другими фракциями, защитники этой точки наносят на 50% меньше урона и получают на 50% больше урона."},
	{"","[Сбор] Бог Боевых искусств, Бог Войны и Бог Сражений могут издать приказ о сборе, призывая членов своей фракции быстро собраться и атаковать выбранную базу."},
	{"","[Поддержка слабых] Фракция, занявшая второе место в войне фракций, получает +1500 боевого духа в следующей войне, а занявшая третье место — +3000."},
	{"","[Союз] Если фракция дважды подряд занимает первое место в войне фракций, либо дважды подряд занимает третье место, вторая и третья фракции последней войны автоматически заключают союз."},
	{"","[Пакт] При подведении итогов войны фракций количество баз и общая честь двух союзных фракций суммируются для рейтинга; убийство игроков союзной фракции даёт вдвое меньше личной чести."},
	{"[Награды]","Игроки с менее чем 50 очками чести не могут получить награды за задания."},
	{"","По окончании войны фракций, согласно рейтингу по числу занятых территорий каждой фракции, игроки, набравшие более 50 очков чести в этой войне, получат награды. За разные места — разные награды."},
	{"","По окончании войны фракций ты получишь награду в зависимости от своего места в личном рейтинге чести."},
}

